import{_ as l,C as t,o as c,c as d,j as e,a as r,G as i,a2 as h}from"./chunks/framework.BgSoyxN5.js";const v=JSON.parse('{"title":"Portfolio Diagnostics Demo: Health, Sector, and Stress Test Reports","description":"Compare model portfolios, inspect holdings, and run TickerForge portfolio diagnostics for health, concentration, sector exposure, and stress tests.","frontmatter":{"title":"Portfolio Diagnostics Demo: Health, Sector, and Stress Test Reports","description":"Compare model portfolios, inspect holdings, and run TickerForge portfolio diagnostics for health, concentration, sector exposure, and stress tests."},"headers":[],"relativePath":"portfolio-diagnostics.md","filePath":"portfolio-diagnostics.md","lastUpdated":1785053778000}'),p={name:"portfolio-diagnostics.md"};function f(g,o,u,m,w,k){const a=t("TickerForgeComplianceDisclaimer"),s=t("TickerForgeTrustBlock"),n=t("TickerForgePortfolioDiagnosticsWidget");return c(),d("div",null,[o[0]||(o[0]=e("h1",{id:"portfolio-diagnostics-widget",tabindex:"-1"},[r("Portfolio Diagnostics Widget "),e("a",{class:"header-anchor",href:"#portfolio-diagnostics-widget","aria-label":'Permalink to "Portfolio Diagnostics Widget"'},"​")],-1)),o[1]||(o[1]=e("p",null,"See how TickerForge evaluates an entire portfolio rather than judging every stock in isolation. Choose between two dated public models, inspect the holdings first, and then run the same Portfolio Diagnostics reports available across TickerForge.",-1)),i(a),i(s,{kind:"portfolio"}),o[2]||(o[2]=e("p",null,[e("strong",null,"Internet Favorites"),r(" begins with widely followed stocks that dominate online investor conversations. "),e("strong",null,"Conservative System"),r(" starts from a quality-first candidate pool and applies business-strength, company-risk, position-size, diversification, and market-regime rules. Both preserve their original launch selections while prices and diagnostics continue to update.")],-1)),i(n,{"api-base":"https://api.ticker-forge.com"}),o[3]||(o[3]=h('<p>Want the faster side-by-side view? Open <a href="/portfolio-comparison">Portfolio Comparison</a> to compare Conservative System and Internet Favorites using the same Portfolio Snapshot lens.</p><h2 id="run-a-free-portfolio-health-check" tabindex="-1">Run a Free Portfolio Health Check <a class="header-anchor" href="#run-a-free-portfolio-health-check" aria-label="Permalink to &quot;Run a Free Portfolio Health Check&quot;">​</a></h2><p>The demo shows how the diagnostics behave on public model portfolios. To analyze your own holdings and cash, use <a href="/import-portfolio">Import Portfolio</a>. That page is the action workflow for a free Portfolio Health Check, concentration review, sector exposure view, and stress-test estimate.</p><div class="portfolio-report-download"><div><span class="portfolio-report-download__kicker">Sample PDF</span><h2>See the report format before you run diagnostics</h2><p>Download a real TickerForge Portfolio Diagnostics PDF to preview the exported snapshot: scores, exposure, concentration, stress scenario, ownership context, insider activity, and diagnostic notes.</p></div><a class="portfolio-report-download__button" href="/reports/tickerforge-portfolio-diagnostics-2026-07-13.pdf" download>Download sample PDF</a></div><h2 id="from-free-diagnostics-to-standard-tracking" tabindex="-1">From Free Diagnostics to Standard Tracking <a class="header-anchor" href="#from-free-diagnostics-to-standard-tracking" aria-label="Permalink to &quot;From Free Diagnostics to Standard Tracking&quot;">​</a></h2><p>The public models are free to inspect. They show how TickerForge explains portfolio health, concentration, sector exposure, stress scenarios, and stock-level evidence across a full basket.</p><p>If you want TickerForge to monitor a real portfolio over time, weekly tracking and risk alerts are Standard features. Free users can receive a portfolio snapshot and then continue in Telegram to create/import the portfolio and start the trial tracking path. If you choose Standard tracking, the widget records the product context and sends you to the <a href="/pricing">Pricing page</a>, where current paid access is activated through Telegram Stars.</p><h2 id="what-you-can-inspect" tabindex="-1">What You Can Inspect <a class="header-anchor" href="#what-you-can-inspect" aria-label="Permalink to &quot;What You Can Inspect&quot;">​</a></h2><p>Choose a model, then start with <strong>Portfolio View</strong> to understand what it owns, how it is allocated, and how its virtual balance is performing. This creates a logical path from portfolio construction to portfolio diagnosis.</p><p>When you are ready, switch to <strong>Analyze</strong>. It opens Portfolio Snapshot first, giving you a concise summary of portfolio health, cash buffer, position and sector breadth, concentration, and an estimated downside scenario.</p><p>The four diagnostic views answer different questions:</p><ul><li><strong>Portfolio Snapshot</strong> shows the most important scores and structural exposures on one screen.</li><li><strong>Health Check</strong> explains strengths, concentration warnings, risk factors, and practical areas to review.</li><li><strong>Sector Allocation</strong> reveals whether diversification is real or whether several holdings depend on the same industry cycle.</li><li><strong>Stress Test</strong> estimates how the portfolio may react to downside and upside market shocks using the same scenario engine used by the Telegram reports.</li></ul><p>The widget is read-only: it demonstrates the portfolio and its diagnostics without creating a portfolio in your account or placing trades. To analyze your holdings, open <a href="/import-portfolio">Import Portfolio</a>. To create a new virtual portfolio using the same construction workflow, open the <a href="/portfolio-builder">Portfolio Builder</a>.</p><h2 id="portfolio-story-risk-and-ownership" tabindex="-1">Portfolio Story, Risk, and Ownership <a class="header-anchor" href="#portfolio-story-risk-and-ownership" aria-label="Permalink to &quot;Portfolio Story, Risk, and Ownership&quot;">​</a></h2><p>Portfolio Snapshot also combines stock-level decision data across the positions it can cover:</p><ul><li><strong>Story Heat</strong> estimates how strongly price leadership, trend persistence, valuation re-rating, growth, and sector participation are reinforcing the market narrative. A high score means the story is already visible in market behavior; it is not an instruction to trade.</li><li><strong>Crowding Risk</strong> measures stretch, vertical price action, valuation pressure, weak confirmation, and market fragility. Higher values mean entry timing and position sizing deserve more caution.</li><li><strong>Top Funds Regime</strong> weights each covered holding by its portfolio size, then shows whether tracked 13F funds are predominantly adding, selling, or sending mixed signals.</li><li><strong>Insider Activity</strong> summarizes the latest open-market insider regime and the combined three-month purchases and sales across covered holdings.</li></ul><p>Coverage is shown beside each block because not every security has complete decision, 13F, or Form 4 data. Missing holdings are excluded from the corresponding weighted score rather than treated as bearish signals.</p><h2 id="why-use-a-model-portfolio" tabindex="-1">Why Use a Model Portfolio? <a class="header-anchor" href="#why-use-a-model-portfolio" aria-label="Permalink to &quot;Why Use a Model Portfolio?&quot;">​</a></h2><p>A stock can look attractive by itself and still make a portfolio weaker. It may duplicate an existing sector exposure, increase market sensitivity, or become too large relative to the rest of the book. A model portfolio makes these relationships easier to see because every report is generated from the same set of positions.</p><p>For a deeper explanation of each report, visit <a href="/portfolio-analysis">Portfolio Analysis</a>. The scoring logic is documented in the <a href="/methodology/portfolio-health-check">Portfolio Health Check methodology</a>, while downside and margin scenarios are covered in the <a href="/methodology/portfolio-stress-test">Portfolio Stress Test methodology</a>.</p><h2 id="continue-with-your-own-portfolio" tabindex="-1">Continue With Your Own Portfolio <a class="header-anchor" href="#continue-with-your-own-portfolio" aria-label="Permalink to &quot;Continue With Your Own Portfolio&quot;">​</a></h2><p>The public model is an educational demonstration, not a recommendation or a promise of future performance. Your own portfolio may have different position sizes, cash needs, tax constraints, broker exposure, and risk tolerance.</p><p>Use the <a href="/stock-widget">Stock Analysis Widget</a> when you want to investigate an individual company before adding it. Then <a href="/import-portfolio">import your portfolio</a> to run the same four diagnostic reports on your own holdings. Advanced access and portfolio features are described on the <a href="/pricing">Pricing page</a>.</p><p><strong><a href="/import-portfolio">Analyze your own portfolio</a></strong></p><h2 id="related-read-next" tabindex="-1">Related / Read Next <a class="header-anchor" href="#related-read-next" aria-label="Permalink to &quot;Related / Read Next&quot;">​</a></h2><ul><li><a href="/import-portfolio">Import your own portfolio</a> — run the same diagnostics on your actual holdings and cash balance.</li><li><a href="/portfolio-comparison">Compare the model portfolios</a> — see their key Snapshot metrics side by side.</li><li><a href="/portfolio-builder">Build a rules-based portfolio</a> — create a new model using quality, risk, and diversification filters.</li><li><a href="/methodology/portfolio-health-check">How portfolio health is calculated</a> — review the scoring and deduction logic.</li><li><a href="/methodology/portfolio-stress-test">How portfolio stress testing works</a> — understand the downside and upside scenarios.</li><li><a href="/blog/how-to-stress-test-your-portfolio">How to stress test your portfolio</a> — practical interpretation guide for stress-test results.</li></ul>',26))])}const b=l(p,[["render",f]]);export{v as __pageData,b as default};
